"use strict";
const techniques=[["🎯","پیام سه‌مرحله‌ای","نکته اصلی، دلیل کوتاه و اقدام بعدی را به ترتیب بگوییم."],["🔎","واژه‌گزینی روشن","واژه‌های مبهم یا اداری را به جمله مشخص و قابل فهم تبدیل کنیم."],["🎙️","لحن و بلندی صدا","قاطع، آرام و محترمانه حرف بزنیم؛ بدون تهدید یا صدای تحقیرآمیز."],["⏸️","سرعت، مکث و تأکید","سرعت بیان را متناسب کنیم؛ پس از پرسش مکث کنیم و نکته اصلی را برجسته کنیم."],["🤝","نگاه، حالت بدن و فاصله","با نگاه طبیعی، وضعیت بدن متعادل و فاصله محترمانه صحبت کنیم."],["🧭","هماهنگی کلام و رفتار","لحن، چهره و عمل ما باید با پیام گفته‌شده هم‌جهت باشند."]];
const techniqueDetails=[{"definition":"یک پیام مؤثر، از مسئله آغاز می‌شود، یک دلیل یا زمینه ضروری می‌گوید و به گام بعد می‌رسد.","example":"«اولویت اول پاسخ مشتری حقوقی است؛ چون موعد نزدیک است؛ شما مسئول هماهنگی تا ظهر هستید.»","pitfall":"شمردن چندین مانع، بدون تعیین مسئله و مسئول."},{"definition":"اطلاعات را درست ولی ساده می‌گوییم؛ اصطلاح فنی و واژه دوپهلو را توضیح می‌دهیم.","example":"به‌جای «فرایند در گردش است»، بگوییم «نتیجه بررسی هنوز نهایی نشده است».","pitfall":"اطمینان‌بخشی مبهم یا قول قطعی بدون اختیار."},{"definition":"حجم صدا و آهنگ جمله را با موقعیت تنظیم می‌کنیم؛ جدیت، مساوی تندی نیست.","example":"«اول واقعیت ثبت را بررسی می‌کنیم؛ بعد درباره اصلاح تصمیم می‌گیریم.» با صدای متوسط.","pitfall":"کلام محترمانه با صدای سرزنشگر یا کنایه‌آمیز."},{"definition":"مکث کوتاه پس از سؤال یا پیش از پیام مهم، فرصت فهم و پاسخ می‌سازد.","example":"«اول تماس با مشتری… [مکث] دوم، گزارش تا ساعت دوازده.»","pitfall":"پشت سر هم حرف زدن، قطع کلام یا پر کردن هر سکوت."},{"definition":"جهت بدن، نگاه طبیعی و فاصله راحت مخاطب را رعایت می‌کنیم، بدون تفسیر قطعی رفتار دیگران.","example":"در جلسه کارکنان به افراد مختلف نگاه می‌کنیم و صفحه را رها می‌کنیم.","pitfall":"فرض اینکه دست‌به‌سینه بودن یعنی مخالفت یا نگاه‌نکردن یعنی دروغ."},{"definition":"همخوانی پیام، لحن و رفتار موجب اعتماد می‌شود؛ تعارض این نشانه‌ها ابهام می‌آورد.","example":"هنگام دعوت به سؤال، واقعاً مکث و فرصت پرسیدن می‌دهیم.","pitfall":"گفتن «هر سؤالی دارید بپرسید» با چهره عصبانی و خروج فوری."}];
const raw=[["رئیس شعبه همتا","دو شعبه، دو پیام متفاوت","مشتری سازمانی از دو شعبه درباره مسئول پیگیری پرونده پاسخ متفاوت گرفته است.","پیام سه‌مرحله‌ای","مشتری می‌گه از هر دو شعبه جواب متفاوت شنیده؛ مسئول پیگیری کیه؟|ما چند تا موضوع داریم؛ سامانه، نامه منطقه، سوابق تماس و چند پرونده باز.|یعنی امروز به مشتری چی بگم؟|همه باید هماهنگ بشن تا بتونیم جواب بدیم.|این دقیقاً همون چیزیه که دیروز هم شنید.|فعلاً بگید در حال بررسی هستیم.","یعنی هنوز هیچ‌کس مسئول پاسخ نیست؟|نکته اصلی اینه که برای پاسخ به مشتری یک نفر مسئول مشخص داشته باشیم.|شعبه شما مسئولیت رو می‌پذیره؟|سوابق دو شعبه رو تا ظهر تطبیق می‌دیم و یک نفر برای پاسخ تعیین می‌کنیم.|یعنی نتیجه پرونده هم معلوم می‌شه؟|نه لزوماً؛ مسئول اطلاع‌رسانی مشخص می‌شه، بدون وعده نتیجه.","ابتدا مسئله اصلی را نام ببر، نه تمام جزئیات را. دلیل کوتاه و اقدام در محدوده اختیار را بیان کن. مسئول پاسخ را از تضمین نتیجه پرونده جدا کن.","سه بخش پیام را با مکث جدا کن؛ هنگام تعیین مسئول، صدای مطمئن و بدون وعده نتیجه داشته باش.","ساختار «مسئله، دلیل، اقدام» ابهام را کم می‌کند.","شفافیت، مجوز قول نتیجه پرونده نیست."],["رئیس شعبه همتا","وقتی گزارش دو شعبه مقایسه می‌شود","گزارش ستاد درباره دو شعبه متفاوت است و رئیس همتا از مقایسه ناراحت شده.","لحن و بلندی صدا","چرا آمار شعبه شما بهتر دیده شده؟ داده‌هامون از یک سامانه‌ست.|ما گزارش‌هامون رو هر روز دقیق کنترل می‌کنیم.|یعنی ما کنترل نمی‌کنیم؟|نه، فقط می‌گم شاید روش جمع‌آوری شما فرق داشته.|شاید تعریف شاخص تفاوت داره.|خب از ستاد بپرسید؛ خیلی پیچیده نیست.","لحنتون انگار ایراد رو از شعبه ما می‌دونه.|متوجه برداشت شما هستم. فعلاً درباره علت اختلاف گزارش شاهد کافی نداریم.|پس چطور بررسی کنیم؟|تعریف شاخص و بازه گزارش رو کنار هم می‌گذاریم؛ بدون قضاوت درباره عملکرد کسی.|اگر اختلاف حل نشد؟|یک پرسش مشترک برای ستاد می‌فرستیم و پاسخ را بین هر دو شعبه به اشتراک می‌گذاریم.","حجم صدا و تأکید را از حالت رقابتی خارج کن. فرض درباره عملکرد شعبه دیگر را به واقعیت تبدیل نکن. پیگیری مشترک را پیشنهاد بده، نه بحث برنده و بازنده.","صدای متوسط، بدون تأکید دفاعی بر «ما»؛ چهره محترمانه و برابر.","لحن می‌تواند پیام پنهان اتهام بسازد.","جمله خنثی با آهنگ برترطلب، همکاری نمی‌آورد."],["معاون شعبه","سه اولویت در یک صبح شلوغ","معاون هم‌زمان با سه درخواست فوری روبه‌روست و نمی‌داند کدام مقدم است.","پیام سه‌مرحله‌ای","برای امروز اولویت اصلی ما کدوم کاره؟|تمدیدها عقب افتاده، گزارش ستاد داریم و مشتری حقوقی هم تماس گرفته.|اول تمدیدها رو انجام بدم؟|بله، ولی گزارش هم تا ظهر باید برسه و مشتری هم منتظر نمونه.|با دو نفر نمی‌تونیم هر سه رو اول انجام بدیم.|یه جوری برنامه‌ریزی کنین که همه برسه.","من هنوز ترتیب رو نمی‌دونم.|شفاف می‌گم: اول پاسخ مشتری؛ دوم گزارش ستاد تا دوازده؛ سوم برنامه تمدیدها تا پایان روز.|برای تماس مشتری مسئول کیه؟|شما هماهنگ کنید، کارشناس قرارداد هم داده‌ها رو آماده کنه.|اگر مشتری و گزارش هم‌زمان شدند؟|همان موقع اطلاع بدین تا اولویت را دوباره تصمیم بگیریم. لطفاً ترتیب رو یک بار بازگو کنین.","اولویت‌ها را شماره‌گذاری و از هم جدا کن. مسئول و موعد معتبر هر کار را اعلام کن. پایان گفت‌وگو فهم مشترک را کنترل کن.","بین اولویت‌ها مکث کوتاه کن؛ شماره هر اولویت و مسئولش را برجسته بگو.","پیام روشن، قابل اجرا و قابل بازگویی است.","انتظار بدون اولویت و اختیار، توقع غیرواقعی ایجاد می‌کند."],["معاون شعبه","ابلاغ تغییر شیفت پاسخ‌گویی","برنامه پاسخ‌گویی آزمایشی تغییر کرده و معاون نگران واکنش کارکنان است.","هماهنگی کلام و رفتار","تغییر شیفت رو چطور اعلام کنیم؟|بگین برای خدمت بهتره و همه باید همکاری کامل داشته باشن.|ممکنه درباره افزایش کار نگران بشن.|جای نگرانی نیست؛ من هم گفتم نظرها رو می‌شنوم.|اگر با اخم اعلام کنیم فکر می‌کنن سؤال ممنوعه.|بگین هرکس مشکلی داشت بعداً مطرح کنه.","پس الان واقعاً فرصت سؤال می‌دیم؟|بله؛ برنامه آزمایشیه. ساعات و مسئولیت‌ها رو روشن می‌کنیم و برای شنیدن دغدغه‌ها وقت می‌گذاریم.|این بار چطور بیانش می‌کنید؟|آرام و کوتاه؛ هدف کاهش انتظار مشتریه نه افزایش نامحدود کار.|اگر کسی محدودیت داشت؟|همون جلسه فرصت بیان می‌دیم و موضوع رو بررسی می‌کنیم، بدون وعده تغییر قطعی.","دعوت به سؤال باید با مکث واقعی همراه باشد. لحن نرم و رفتار آرام با پیام احترام سازگار است. محدوده آزمایشی و زمان بازنگری را روشن کن.","دعوت به سؤال را با مکث واقعی و نگاه پذیرا همراه کن، نه عجله برای خروج.","هماهنگی کلام و رفتار بخشی از صداقت مدیریتی است.","دعوت به مشارکت، تعهد به پذیرش همه پیشنهادها نیست."],["کارشناس شعبه","اشتباه ثبت که هنوز قطعی نیست","کارشناس احتمال می‌دهد تاریخ مدرکی را اشتباه ثبت کرده باشد.","لحن و بلندی صدا","احتمال می‌دم تاریخ یکی از مدارک اشتباه باشه.|چرا همون موقع کنترل نکردین؟|هنوز مطمئن نیستم؛ خواستم زود خبر بدم.|نمی‌تونیم هر روز این نوع خطا داشته باشیم.|پس اول اصل مدرک رو با ثبت تطبیق بدم؟|اول گزارش علت اشتباه رو بنویسین، بعد بررسی کنیم.","یعنی درباره خطایی که هنوز قطعی نیست گزارش علت بدم؟|نه؛ ترتیب رو اصلاح می‌کنیم. ممنون که زود گفتین. اول ثبت و اصل مدرک رو تطبیق بدین.|اگر خطا تأیید شد چه کار کنیم؟|طبق فرایند مصوب اصلاح می‌کنیم؛ بعد علت رو بررسی می‌کنیم.|من نمونه ثبت رو آماده می‌کنم.|خوبه. هدف روشن‌شدن واقعیت پرونده‌ست، نه سرزنش یک نفر.","با صدای متوسط اما جدی صحبت کن. از تأیید زودهنگام خطا یا سرزنش فرد پرهیز کن. واقعیت، بررسی و گام بعد را از هم تفکیک کن.","هنگام گزارش خطا صدایت را بالا نبر؛ به سمت فرد با انگشت اشاره نکن.","جدیت، مساوی تندی نیست.","گزارش به‌موقع باید با دقت و مسئولیت‌پذیری پاسخ بگیرد."],["کارشناس شعبه","پیشنهادی که نصفه می‌ماند","کارشناس برای کاهش رفت‌وبرگشت مشتری ایده‌ای دارد ولی مدیر پی‌درپی می‌پرد وسط حرفش.","سرعت، مکث و تأکید","درباره صف مشتری‌ها یک پیشنهاد دارم.|خوب، سریع بگید چون کار زیاد داریم.|اگر نقص مدرک رو همون ابتدا...|بله، جدا کنیم، اینو قبلاً گفتیم. بعدش؟|منظورم شیوه اطلاع‌رسانی به مشتری بود.|پس فردا یادداشت کنین تا بررسی کنیم.","فکر می‌کنم هنوز پیشنهادم رو کامل نگفتم.|بفرمایین کامل توضیح بدین. [مکث کوتاه] کجای اطلاع‌رسانی مشکل داره؟|مشتری دقیق نمی‌فهمه کدوم مدرک کم هست و چند بار تماس می‌گیره.|پس یک پیام واحد با فهرست نقص‌های تأییدشده پیشنهاد می‌کنین؟|بله، از مسیر رسمی ارسال بشه.|خوبه؛ یک نمونه فرضی آماده کنیم و نتیجه رو بسنجیم.","بعد از سؤال مکث کن و اجازه تکمیل بده. سرعت بیان را به نیاز مخاطب نزدیک کن. جمله طرف مقابل را به‌جای او کامل نکن.","پس از پرسش سکوت کوتاه داشته باش؛ نگاه به کارشناس و نه ساعت.","مکث، مهارت ارتباطی مدیر است نه ضعف او.","سرعت زیاد ممکن است فرصت مشارکت را از بین ببرد."],["مشتری","پاسخ روشن به زیان‌دیده","مراجعه‌کننده اصطلاحات اداریِ وضعیت پرونده را متوجه نمی‌شود.","واژه‌گزینی روشن","پرونده خسارت من چرا هنوز جلو نرفته؟|در مرحله تطبیق مستندات و گردش کار ارزیابی قرار داره.|یعنی خسارتم تأیید شده؟|فرایند نهایی نشده و وضعیت در سامانه باید بررسی بشه.|پس قدم بعدی من چیه؟|بعد از انجام مراحل اطلاع‌رسانی می‌شه.","من از این اصطلاح‌ها چیزی نمی‌فهمم.|حق دارید؛ ساده بگم. هنوز درباره نتیجه نهایی تصمیم گرفته نشده.|یعنی باید مدرک تازه بیارم؟|تا وضعیت مدارک رو از مسیر رسمی بررسی نکنیم، نمی‌تونم بگم چیزی کم هست.|پس فعلاً منتظر بمونم؟|وضعیت پرونده و اگر نقصی داشت، فهرست دقیقش را از مسیر مجاز اعلام می‌کنیم.","اصطلاح فنی را به جمله معمولی تبدیل کن. وضعیت فعلی را از اقدام بعدی جدا بگو. بدون بررسی، وجود نقص یا زمان پرداخت را قطعی نگو.","سرعت متناسب با مشتری؛ اصطلاح فنی را در جمله جداگانه توضیح بده.","شفافیت از پیچیدگی واژگان نمی‌آید.","قول غیرمجاز، جای توضیح ساده نیست."],["مشتری","نتیجه قطعی نیست؛ لحن باید روشن باشد","زیان‌دیده با اضطراب می‌پرسد آیا خسارت امروز پرداخت می‌شود.","هماهنگی کلام و رفتار","امروز خسارت من پرداخت می‌شه؟|نگران نباشید؛ پیگیری می‌کنیم.|من نمی‌تونم هر روز بیام.|احتمالاً همین امروز درست می‌شه.|یعنی شما قول می‌دید؟|نه دقیقاً؛ فعلاً منتظر بمونید.","پس «امروز درست می‌شه» یعنی چی؟|جمله من دقیق نبود. نتیجه پرداخت هنوز تأیید نشده و من نمی‌تونم زمان قطعی بدم.|پس از کجا وضعیت رو بفهمم؟|از مسیر رسمی اطلاع‌رسانی، وضعیت قابل اعلام رو مشخص می‌کنیم.|یعنی قول پرداخت نمی‌دید؟|قول نتیجه نمی‌دم؛ اما درباره وضعیت واقعی شفاف صحبت می‌کنم.","صداقت و همدلی را هم‌زمان بیان کن. عبارت غیرقطعی را با لحن بیش‌ازحد مطمئن نگو. نگاه و وضعیت بدنی آرام، همراه توضیح روشن باشد.","با صدای آرام و صریح، نبود نتیجه قطعی را منتقل کن؛ لبخند را به‌جای وعده قرار نده.","اطمینان‌بخشی بدون واقعیت، اعتماد را تضعیف می‌کند.","هماهنگی صدا و کلام، شفافیت را تقویت می‌کند."],["نماینده","درخواست مبهمِ پیگیری","نماینده از شعبه پیگیری فوری می‌خواهد ولی نمی‌داند مسیر و مسئول چیست.","واژه‌گزینی روشن","پرونده بیمه‌گذار ما هنوز تعیین تکلیف نشده.|باشه؛ همه داریم پیگیری می‌کنیم.|من به کی تماس بگیرم؟|به کارشناسان بگین جلو ببرن؛ همه در جریانن.|از کدوم واحد شروع کنم؟|هر جا مرتبطه تماس بگیرین تا سریع‌تر بشه.","اگر به همه زنگ بزنم دوباره گیج می‌شم.|درست می‌گین. موضوع شما مشخص‌کردن مسیر پاسخ‌گویی پرونده است.|الان قدم بعد چیه؟|شماره پرونده رو از مسیر رسمی می‌گیریم، مسئول بررسی رو مشخص می‌کنیم و وضعیت مجاز رو اعلام می‌کنیم.|زمان تماس بعدی رو می‌گین؟|اگر زمان معتبر داشتیم می‌گیم؛ زمان ساختگی قول نمی‌دیم.","به‌جای «همه در جریان‌اند»، موضوع و مسیر رسمی پیگیری را نام ببر. جمله کوتاه و مشخص بساز تا نماینده بداند درخواست را از کجا پیگیری کند. مسئول پاسخ را پس از تعیین واقعی معرفی کن؛ اسم یا موعد فرضی نگو.","جمله‌های کوتاه و تمرکز بر مسیر رسمی؛ از فهرست‌کردن واحدها پرهیز کن.","«همه پیگیرند» جای بیان روشنِ مسئول و مسیر را نمی‌گیرد.","واژه روشن همراه با محدودیت واقعی، انتظار را مدیریت‌پذیر می‌کند."],["نماینده","وقتی نماینده از لحن پاسخ ناراحت است","نماینده پس از تماس تلفنی ناخوشایند به شعبه مراجعه کرده و رو‌در‌رو با رئیس شعبه گفت‌وگو می‌کند.","نگاه، حالت بدن و فاصله","کارشناس شما تلفنی طوری جواب داد که انگار مزاحمش شده بودم.|[درحالی‌که به گوشی نگاه می‌کند] ایشون آدم دقیقیه و معمولاً محترمانه جواب می‌ده.|من درباره نیتش حرف نمی‌زنم؛ لحن تماس من رو ناراحت کرد.|[همچنان به گوشی نگاه می‌کند] شاید برداشت شما این‌طور بوده؛ ما که قصد بدی نداریم.|من دارم با شما حرف می‌زنم؛ می‌خوام بدونم این موضوع چطور بررسی می‌شه.|بفرمایید دوباره تماس بگیرید؛ حتماً بهتر می‌شه.","ممکنه یک لحظه به موضوعی که گفتم توجه کنید؟|[گوشی را کنار می‌گذارد و رو به نماینده می‌نشیند] بفرمایید؛ از تجربه تماس ناراحت شدید. می‌خوام دقیق بدونم چه اتفاقی افتاد.|لحن همکارتون سرد بود؛ انتظار داشتم محترمانه جواب بگیرم.|ممنون که توضیح دادین. بدون قضاوت درباره قصد همکار، موقعیت تماس رو بررسی می‌کنم.|برای پیگیری بعدی با چه کسی صحبت کنم؟|بعد از بررسی، مسیر پاسخ‌گویی مناسب رو مشخص می‌کنیم؛ درباره نتیجه بررسی از الان قول نمی‌دم.","هنگام شنیدن شکایت، گوشی را کنار بگذار و رو به مخاطب باش. از اشاره دفاعی با دست یا نگاه‌کردن مداوم به صفحه پرهیز کن؛ فاصله محترمانه را رعایت کن. از یک حالت بدن درباره احساس مخاطب نتیجه نگیر؛ تجربه او را مستقیم بپرس.","گوشی را کنار بگذار؛ رو به نماینده باش و فاصله حرفه‌ای را رعایت کن.","حالت بدن باید از توجه واقعی حمایت کند، نه نقش‌بازی‌کردن را جایگزین آن کند.","نشانه غیرکلامی بدون زمینه و پرسش از مخاطب، تفسیر قطعی ندارد."],["ستاد","گزارش فوری در سه جمله","ستاد از افت شاخص رسیدگی شعبه توضیح کوتاه می‌خواهد.","سرعت، مکث و تأکید","نرخ رسیدگی پایین اومده. مهم‌ترین علت چیه؟|چند مسئله داریم؛ نیرو، صف، پرونده ناقص، سرعت ثبت و گاهی اختلال.|کدوم مهم‌تره؟|هنوز دقیق نیست ولی مجموعه عوامل اثر گذاشته.|تا کی جواب روشن می‌دید؟|باید گزارش مفصل تهیه کنیم.","برای امروز فقط وضعیت و گام بعد رو می‌خوام.|خلاصه در سه بخش: افت شاخص ثبت شده؛ علت اصلی هنوز تأیید نشده؛ سه پرونده نمونه رو بررسی می‌کنیم.|مسئول بررسی کیه؟|معاون داده‌ها رو جمع می‌کنه و من جمع‌بندی رو ارسال می‌کنم.|اگر به زمان بیشتر نیاز داشتید؟|پیش از موعد خبر می‌دم؛ بدون شواهد علت قطعی اعلام نمی‌کنم.","درخواست کوتاه را با سه جمله پاسخ بده. بین واقعیت و فرضیه مکث و تفکیک ایجاد کن. مسئول و موعد معتبر را روشن بگو.","بین واقعیت، عدم‌قطعیت و گام بعد مکث کن؛ با ریتمی قابل فهم گزارش بده.","مکث حساب‌شده، علامت تفکر است.","اختصار حرفه‌ای با پنهان‌کاری تفاوت دارد."],["ستاد","تبدیل ابلاغیه به گفت‌وگوی تیمی","رئیس شعبه باید تصمیم جدید ستاد را به کارکنان منتقل کند.","نگاه، حالت بدن و فاصله","ابلاغیه جدید رو چطور به تیم می‌گید؟|[با نگاه به صفحه رایانه] متن رو در کانال رسمی می‌فرستیم؛ همه می‌خونن.|فقط ارسال متن ممکنه ابهام ایجاد کنه.|[بی‌آنکه از صفحه چشم بردارد] درسته، ولی جلسه مفصل وقت می‌گیره.|دو بندش درباره پاسخ مشتریه و باید درست فهمیده بشه.|اگر سؤال داشتند، بعداً از شما می‌پرسن.","به نظرم توضیح کوتاه خودتون می‌تونه ابهام رو کم کنه.|[برگه را کنار می‌گذارد و رو به مخاطب می‌نشیند] درست می‌گین؛ ارسال متن به‌تنهایی کافی نیست.|در جلسه کوتاه چه نکاتی رو می‌گید؟|چه چیزی تغییر کرده، چه چیزی ثابت مونده و از چه زمانی اجرا می‌شه.|اگر کارکنان برداشت متفاوتی داشتند؟|[مکث می‌کند] با سؤال فهم مشترک رو بررسی می‌کنیم؛ ابهام‌ها رو برای ستاد ثبت می‌کنیم.","هنگام توضیح، از روی صفحه چشم بردار و نگاه را طبیعی پخش کن. تغییر، بخش ثابت و زمان اجرا را جدا بیان کن. زبان بدن دیگران را تفسیر قطعی نکن؛ از فهمشان سؤال کن.","هنگام توضیح ابلاغیه برگه را کنار بگذار و نگاه را طبیعی میان افراد تقسیم کن.","نگاه متناسب، مکمل پیام روشن است نه جایگزین آن.","حضور حرفه‌ای با نمایش سلطه تفاوت دارد."]];
