const state={current:-1,step:0,max:0}, stages=["اجرای اول","قواعد","اجرای دوم","جمع‌بندی"];
const digits=n=>String(n).replace(/[0-9]/g,d=>"۰۱۲۳۴۵۶۷۸۹"[+d]);
const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function bubble(lines,role,b){return '<div class="s4-chat">'+lines.map((line,i)=>'<div class="s4-bubble '+(i%2?"manager":"")+'"><small>'+(i%2?"رئیس شعبه · "+escapeHtml(b.manager.name):escapeHtml(role)+" · "+escapeHtml(b.partner.name))+'</small><p>'+escapeHtml(line)+'</p></div>').join("")+'</div>'}
function renderBriefs(b,c){
 const roleCard=(role,title,who)=>'<article class="s4-persona"><button type="button" class="s4-persona-btn" data-s4-role="'+who+'" aria-expanded="false" aria-controls="s4-role-'+who+'"><span class="s4-persona-icon" aria-hidden="true">'+(who==="manager"?"👔":"👤")+'</span><span class="s4-persona-title"><strong>'+title+' · '+escapeHtml(role.name)+'</strong></span><span class="s4-persona-open">مشاهده نقش ＋</span></button><div class="s4-persona-info" id="s4-role-'+who+'" hidden><p><b>سبک ارتباطی:</b> '+escapeHtml(role.style)+'</p><p><b>هدف گفت‌وگو:</b> '+escapeHtml(role.goal)+'</p><p><b>اطلاعات اختصاصی این نقش:</b> '+escapeHtml(role.private)+'</p><p><b>راهنمای ایفای نقش:</b> '+escapeHtml(role.act)+'</p></div></article>';
 return '<section class="s4-personas"><h4>شخصیت‌های این موقعیت</h4><p class="s4-role-hint">هر نفر برگه نقش خودش را باز کند؛ اطلاعات طرف مقابل را از راه گفت‌وگو کشف کنید.</p><div class="s4-persona-grid">'+roleCard(b.manager,"رئیس شعبه","manager")+roleCard(b.partner,c.role,"partner")+'</div></section>';
}
function togglePersona(button){
 const pane=document.getElementById("s4-role-"+button.getAttribute("data-s4-role"));if(!pane)return;
 const opening=button.getAttribute("aria-expanded")!=="true";pane.hidden=!opening;button.setAttribute("aria-expanded",String(opening));
 const label=button.querySelector(".s4-persona-open");if(label)label.textContent=opening?"بستن نقش −":"مشاهده نقش ＋";
}
let activeTechnique=-1;
function showTechniqueDetail(index){
 const el=document.getElementById("s4-tech-detail");if(!el)return;
 activeTechnique=index===activeTechnique?-1:index;
 document.querySelectorAll("[data-s4-tech]").forEach(btn=>btn.setAttribute("aria-expanded",String(Number(btn.getAttribute("data-s4-tech"))===activeTechnique)));
 if(activeTechnique<0){el.innerHTML="";el.hidden=true;return;}
 const t=techniques[activeTechnique],d=techniqueDetails[activeTechnique];el.hidden=false;
 el.innerHTML='<div class="s4-tech-detail-head"><div><small>تکنیک '+digits(activeTechnique+1)+' از ۶</small><h3>'+escapeHtml(t[1])+'</h3></div><button type="button" data-s4-tech-close aria-label="بستن توضیح تکنیک">×</button></div>'+
 '<div class="s4-tech-detail-content"><div><b>تعریف کاربردی</b><p>'+escapeHtml(d.definition)+'</p></div><div><b>مثال در شعبه</b><p>'+escapeHtml(d.example)+'</p></div><div class="s4-tech-pitfall"><b>خطای رایج</b><p>'+escapeHtml(d.pitfall)+'</p></div></div>';
 if(typeof el.scrollIntoView==="function")el.scrollIntoView({behavior:"smooth",block:"nearest"});
}
function showStage(){
 const host=document.getElementById("s4-focus");if(!host)return;
 if(state.current<0){host.innerHTML="";return;}
 const c=cases[state.current],b=briefs[state.current],i=state.current,t=state.step;
 const tabs='<nav class="s4-tabs" aria-label="چهار مرحله گفت‌وگو">'+stages.map((name,j)=>'<button type="button" data-s4-step="'+j+'" aria-current="'+(t===j?"step":"false")+'" class="'+(j===t?"active":"")+'" '+(j>state.max?"disabled":"")+'>'+(j>state.max?"🔒 ":"")+name+'</button>').join("")+'</nav>';
 const roles=t===0?renderBriefs(b,c):'<details class="s4-role-access"><summary>👥 مشاهده دوباره برگه‌های شخصیت‌ها</summary>'+renderBriefs(b,c)+'</details>';
 let content="";
 if(t===0){
   content='<h4>اجرای اول · پیش از مشاهده قواعد</h4>'+bubble(c.before,c.role,b)+'<div class="s4-observer"><b>پرسش تشخیصی برای مشاهده‌گران</b><p>'+escapeHtml(b.probe)+'</p></div>';
 }
 if(t===1){
   content='<h4>قواعد اختصاصی این کیس</h4><div class="s4-rule-list">'+b.rules.map((x,j)=>'<div class="s4-rule-item"><span>'+digits(j+1)+'</span><p>'+escapeHtml(x)+'</p></div>').join("")+'</div>'+
   '<details class="s4-feedback-extra"><summary>👁 نکات مشاهده برای مدرس</summary><p><b>شاخص اصلی:</b> '+escapeHtml(b.watch)+'</p><p><b>خطای قابل اجتناب:</b> '+escapeHtml(b.avoid)+'</p><p><b>لحن و رفتار غیرکلامی:</b> '+escapeHtml(c.delivery)+'</p></details>';
 }
 if(t===2){
   content='<h4>اجرای دوم · ادامه زنده همان گفت‌وگو</h4>'+
   '<div class="s4-practice"><strong>نوبت اجرای شماست</strong><p>از آخرین جمله اجرای اول ادامه بدهید. رئیس شعبه باید بدون تکرار شروع مکالمه، مسیر گفت‌وگو را با فن بیان مدیریتی اصلاح کند. متن مرجع را فقط بعد از اجرای دو نفر باز کنید.</p><div class="s4-timing">۲ دقیقه گفت‌وگوی زنده · سپس مشاهده نمونه</div></div>'+
   '<details class="s4-sample"><summary>🗣 مشاهده نمونه حرفه‌ای ادامه گفت‌وگو</summary><p class="s4-soft">نمونه راهنماست، نه متن لازم‌الحفظ. هر دو نقش با واژه‌های طبیعی خودشان صحبت کنند.</p>'+
   bubble(c.after,c.role,b)+'</details>';
 }
 if(t===3){
   content='<h4>جمع‌بندی · دو نکته کلیدی</h4><div class="s4-summary">'+c.keys.map((x,j)=>'<div><span>'+digits(j+1)+'</span><p>'+escapeHtml(x)+'</p></div>').join("")+'</div>'+
   '<div class="s4-feedback-panel"><h4>بازخورد مشاهده‌محور</h4><div class="s4-behavior-check"><b>چک‌لیست سه‌موردی مشاهده</b><ul><li>پیام اصلی برای مخاطب روشن بود؟</li><li>لحن و رفتار با موقعیت متناسب بود؟</li><li>'+escapeHtml(b.watch)+'</li></ul></div><p><b>معیار این کیس:</b> '+escapeHtml(b.watch)+'</p><p><b>پرسش مدرس:</b> '+escapeHtml(b.feedback)+'</p><p><b>انتقال به محیط کار:</b> '+escapeHtml(b.transfer)+'</p><small>Feedback را به جمله و رفتار قابل مشاهده ارجاع دهید؛ نه قضاوت درباره شخصیت مجری.</small></div>';
 }
 const next=t===3?'<button class="s4-primary" type="button" data-s4-nextcase>کیس بعدی ←</button>':'<button class="s4-primary" type="button" data-s4-next>مرحله بعد: '+stages[t+1]+' ←</button>';
 const meter='<div class="s4-progress" role="progressbar" aria-label="پیشرفت در ۱۲ کیس" aria-valuemin="0" aria-valuemax="12" aria-valuenow="'+(i+1)+'"><span style="width:'+(((i+1)/12)*100).toFixed(2)+'%"></span></div>';
 host.innerHTML='<article class="s4-work"><div class="s4-workhead"><div><small>کیس '+digits(i+1)+' از ۱۲ · '+escapeHtml(c.role)+'</small><h3>'+escapeHtml(c.title)+'</h3></div><button type="button" data-s4-close class="s4-close" aria-label="بستن کیس و بازگشت به فهرست">×</button></div>'+meter+
 '<p class="s4-scene">'+escapeHtml(c.scene)+'</p>'+tabs+roles+'<div class="s4-stage">'+content+'</div><div class="s4-actions">'+next+'<button type="button" class="s4-secondary" data-s4-close>بازگشت به فهرست ۱۲ کیس</button></div></article>';
}
function select(n){
 if(n<0||n>=cases.length)return;
 state.current=n;state.step=0;state.max=0;
 const lab=document.querySelector(".s4-lab");if(lab)lab.classList.add("s4-active");
 document.querySelectorAll(".s4-case").forEach((el,i)=>{el.classList.toggle("selected",i===n);el.setAttribute("aria-expanded",String(i===n))});
 showStage();
 const panel=document.getElementById("s4-focus");
 if(panel&&typeof panel.scrollIntoView==="function")panel.scrollIntoView({behavior:"smooth",block:"start"});
}
function close(){
 state.current=-1;state.step=0;state.max=0;
 const lab=document.querySelector(".s4-lab");if(lab)lab.classList.remove("s4-active");
 document.querySelectorAll(".s4-case").forEach(el=>{el.classList.remove("selected");el.setAttribute("aria-expanded","false")});
 showStage();
}
